R=Path(__file__).resolve().parent;V=Path('/workspace/scratch/PGAM5_myeloid_reference_v2');names=['GSE151530','GSE149614','GSE189903','GSE242889','GSE202642'];inputs={n:V/(n+'_harmonized_counts_QC.h5ad') if n in names[:3] else R/(n+'_marker_consistent_macrophages.h5ad') for n in names};loaded={n:ad.read_h5ad(p,backed='r') for n,p in inputs.items()};audit=[];patient_checks=[];cohorts=[]
for mode,folder in [('unadjusted',R),('cohort_centered',R/'cohort_centered_sensitivity')]:
 model=json.loads((folder/'locked_state_classifier.json').read_text());assert 'PGAM5' not in model['features'];cycles=set((R/'cell_cycle_genes.txt').read_text().split());assert not set(model['features'])&cycles;mean=np.array(model['feature_mean']);sd=np.array(model['feature_SD']);components=np.array(model['PCA_components']);pmean=np.array(model['PCA_mean']);cent=np.array(model['PCA_centroids']);radius=np.array(model['squared_distance_q95']);co=pd.read_csv(folder/'state_PGAM5_association_by_cohort.csv');don=pd.read_csv(folder/'state_PGAM5_association_by_donor.csv')
 for n in names:
  o=pd.read_csv(folder/(n+'_macrophage_state_metadata.csv.gz'));a=loaded[n];gi=a.var_names.get_indexer(model['features']);assert (gi>=0).all();pgi=a.var_names.get_loc('PGAM5');ci=a.var_names.get_indexer(model['cycling_genes']);assert (ci>=0).all();offset=np.load(folder/(n+'_feature_cohort_offset.npy')) if mode=='cohort_centered' else np.zeros(len(gi));cohorts.append({'mode':mode,'dataset':n,'retained_macrophages':len(o),'PGAM5_detected':int(o.PGAM5_raw.gt(0).sum()),'donor_units':o.donor_id.nunique(),'mapped_fraction':o.state.ne('Unknown_state').mean()})
  for _,row in o.sample(n=min(20,len(o)),random_state=42).iterrows():
   i=a.obs_names.get_loc(row.cell_id);raw=a.X[i,:].toarray().ravel();total=float(a.obs.total_counts.iloc[i]);pg=float(raw[pgi]);pgc=pg/total*10000;assert pg==row.PGAM5_raw and np.isclose(pgc,row.PGAM5_CP10k,atol=1e-5,rtol=1e-5);x=np.log1p(raw[gi]/total*10000)-offset;scaled=np.clip((x-mean)/sd,-10,10);pc=(scaled-pmean)@components.T;ds=((cent-pc)**2).sum(1);order=np.argsort(ds);margin=(ds[order[1]]-ds[order[0]])/max(ds[order[1]],1e-12);state=model['centroid_states'][order[0]];state='Unknown_state' if ds[order[0]]>1.5*radius[order[0]] or margin<.02 else state
   if (raw[ci]>0).sum()>=2:state='Cycling_macrophage'
   assert state==row.state;assert np.isclose(ds[order[0]],row.mapping_distance_squared,rtol=1e-4,atol=.02);audit.append({'mode':mode,'dataset':n,'cell_id':row.cell_id,'reconstructed_state':state,'stored_state':row.state,'PGAM5_CP10k_error':abs(pgc-row.PGAM5_CP10k),'mapping_squared_distance_error':abs(ds[order[0]]-row.mapping_distance_squared)})
  for _,rr in co[co.dataset.eq(n)].iterrows():
   inside=o[o.state.eq(rr.state)];rest=o[o.state.ne(rr.state)];assert len(inside)==rr.state_cells and int(inside.PGAM5_raw.gt(0).sum())==rr.state_PGAM5_detected
  for _,rr in don[don.dataset.eq(n)&don.association_evaluable].iterrows():
   t=o[o.donor_id.eq(rr.donor)];s=t[t.state.eq(rr.state)];r=t[t.state.ne(rr.state)];value=(sum(float(z) for z in s.PGAM5_CP10k)/len(s)+.05)/(sum(float(z) for z in r.PGAM5_CP10k)/len(r)+.05);assert np.isclose(value,rr.PGAM5_CP10k_ratio,atol=1e-10);patient_checks.append({'mode':mode,'dataset':n,'donor':rr.donor,'state':rr.state,'independent_ratio':value,'reported_ratio':rr.PGAM5_CP10k_ratio})
for a in loaded.values():a.file.close()
